/// The constants of the module `path`, as its `names` function answers them: a
/// map from each constant's name to its value.
fn names(path: &str) -> Value {
    Value::Object(constants().into_iter().filter(|(module, _, _)| *module == path).map(|(_, name, value)| (name.to_string(), value)).collect())
}

/// Calls `method` on the object `handle` stands for, by the handle's kind; a
/// kind with no methods answers that it has none.
pub(crate) fn dispatch_kind<'c>(table: &mut CallTable<'c>, handle: Handle, method: &str, args: &Args<'_>) -> Result<Value, ExtError> {
    match handle.kind {
        HandleKind::FeatureBuilder => feature_builder(table, handle, method, args),
        HandleKind::StageCx => stage_cx(table, handle, method, args),
        HandleKind::StageOut => stage_out(table, handle, method, args),
        HandleKind::TablePiece => extra::table_piece(table, handle, method, args),
        HandleKind::ExtTableRead => ext_table_read(table, handle, method, args),
        HandleKind::TreesTable => trees_table(table, handle, method, args),
        HandleKind::Node => node(table, handle, method, args),
        HandleKind::KeyVals => key_vals(table, handle, method, args),
        HandleKind::KeyValEntry => key_val_entry(table, handle, method, args),
        HandleKind::ExpandCx => expand_cx(table, handle, method, args),
        HandleKind::Expander => expander(table, handle, method, args),
        HandleKind::UserDefinition => user_definition(table, handle, method, args),
        HandleKind::ModeVariant => mode_variant(table, handle, method, args),
        HandleKind::LoweringRule => lowering_rule(table, handle, method, args),
        HandleKind::Lowerer => lowerer(table, handle, method, args),
        HandleKind::ElementDef => element_def(table, handle, method, args),
        HandleKind::RewriteCx => rewrite_cx(table, handle, method, args),
        HandleKind::Restager => restager(table, handle, method, args),
        HandleKind::RestagedArgument => restaged_argument(table, handle, method, args),
        HandleKind::RestagedSlot => restaged_slot(table, handle, method, args),
        HandleKind::LoweredTrees => lowered_trees(table, handle, method, args),
        HandleKind::HostService => host_service(table, handle, method, args),
        HandleKind::Files => files(table, handle, method, args),
        HandleKind::ProviderCx => provider_cx(table, handle, method, args),
        HandleKind::TemplateCx => template_cx(table, handle, method, args),
        HandleKind::FlmDiagnostics => flm_diagnostics(table, handle, method, args),
        HandleKind::Counters => extra::counters(table, handle, method, args),
        HandleKind::Anchors => extra::anchors(table, handle, method, args),
        HandleKind::ValueBindings => value_bindings(table, handle, method, args),
        HandleKind::CompiledTemplate
        | HandleKind::PlaceholderBindings
        | HandleKind::Staged
        | HandleKind::Stage
        | HandleKind::Expand
        | HandleKind::LowerCx
        | HandleKind::Lower
        | HandleKind::RewriteStage
        | HandleKind::LibraryStage
        | HandleKind::CitationProvider
        | HandleKind::CitationEntry
        | HandleKind::TemplateModule
        | HandleKind::Module
        | HandleKind::Referenceable
        | HandleKind::Sectioning
        | HandleKind::ArgDef
        | HandleKind::BuiltLang
        | HandleKind::LateInit
        | HandleKind::Finalizer
        | HandleKind::TemplateLanguage => Err(no_method(handle.kind, method)),
    }
}

